//! Stack-Agent's AppPort contract digest against vectors generated by AppPort's reference implementation
//! (`tests/fixtures/appport-capability-digest/generate.mjs`, `@appport/protocol`). A difference here means
//! a pinned capability would be withheld, or worse accepted, for the wrong reason.

use std::path::Path;

use chip_cli::host_capabilities::digest::{canonical_json, capability_digest, digest_of};
use serde_json::Value;

fn fixture(name: &str) -> Value {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/appport-capability-digest")
        .join(name);
    serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap()
}

#[test]
fn canonical_json_and_digests_match_the_reference_implementation() {
    let vectors = fixture("vectors.json");
    let cases = vectors["canonical"].as_array().unwrap();
    assert!(cases.len() >= 9);
    for case in cases {
        let id = case["id"].as_str().unwrap();
        let value: Value = serde_json::from_str(case["json"].as_str().unwrap()).unwrap();
        assert_eq!(
            canonical_json(&value),
            case["canonical"].as_str().unwrap(),
            "canonical JSON for `{id}`"
        );
        assert_eq!(
            digest_of(&value),
            case["digest"].as_str().unwrap(),
            "digest for `{id}`"
        );
    }
}

#[test]
fn capability_digests_match_the_reference_implementation() {
    let vectors = fixture("vectors.json");
    for case in vectors["capabilities"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let manifest = match case["manifest"].as_str().unwrap() {
            "inline" => case["inline"].clone(),
            file => fixture(file),
        };
        let got = capability_digest(
            &manifest,
            case["name"].as_str().unwrap(),
            case["version"].as_u64().unwrap(),
        );
        assert_eq!(
            got.as_deref(),
            case["digest"].as_str(),
            "capability digest for `{id}`"
        );
    }
}

#[test]
fn compatible_providers_share_a_digest_and_a_breaking_change_does_not() {
    let a = capability_digest(&fixture("payments-a.manifest.json"), "payments.charge", 1).unwrap();
    let c = capability_digest(&fixture("payments-c.manifest.json"), "payments.charge", 1).unwrap();
    assert_ne!(a, c, "provider C renamed a required output field");
}
